mapper.select:
SELECT COUNT(DISTINCT u.id)
FROM public.users u
INNER JOIN public.tenant_memberships m
ON m.user_id = u.id AND m.tenant_key = #{tenantKey}


        (
        LOWER(u.email) LIKE LOWER(CONCAT('%', #{search}, '%'))
        OR LOWER(u.first_name) LIKE LOWER(CONCAT('%', #{search}, '%'))
        OR LOWER(u.last_name) LIKE LOWER(CONCAT('%', #{search}, '%'))
        )


        AND u.status = #{status}

mapper.update:
UPDATE public.users
SET first_sign_in_at = #{firstSignInAt}
WHERE id = #{userId} AND first_sign_in_at IS NULL

UPDATE public.users
SET last_global_signout_at = #{lastGlobalSignoutAt}
WHERE id = #{userId}

